text:
{
  "title": "NTT法の改正",
  "lead": {
    "es": "日本電信電話株式会社《にっぽんでんしんでんわかぶしきがいしゃ》（NTT）などのきまりを変《か》える法律《ほうりつ》です。",
    "hs": "日本電信電話株式会社（NTT）などについて、研究の責務《せきむ》をなくし、社名の変更《へんこう》をできるようにし、外国籍《がいこくせき》の役員の規制をゆるめるなどの法律です。",
    "std": "日本電信電話株式会社等について、電気通信技術の研究に係る責務の廃止、商号変更の容認、外国籍の人の役員就任規制の緩和等を行う法律。",
    "univ": "日本電信電話株式会社、東日本電信電話株式会社及び西日本電信電話株式会社について、電気通信技術に関する研究に係る責務を廃止するとともに、商号の変更を可能とするほか、日本の国籍を有しない人が取締役又は監査役に就くことを禁止する規制を緩和する等の措置を講ずる法律。"
  },
  "facts": [
    {
      "es": "NTTなどが、電話《でんわ》や通信《つうしん》の技術《ぎじゅつ》の研究《けんきゅう》を進《すす》めて広《ひろ》めなければならないというきまりをなくします。",
      "hs": "NTTなど（日本電信電話株式会社、東日本電信電話株式会社、西日本電信電話株式会社）が、電気通信技術の研究を進めて成果を広める責務《せきむ》（はたすべき務め）を廃止《はいし》します。",
      "std": "日本電信電話株式会社等の、電気通信技術に関する研究の推進とその成果の普及の責務を廃止する。",
      "univ": "日本電信電話株式会社等の電気通信技術に関する研究の推進及びその成果の普及の責務を廃止する。"
    },
    {
      "es": "NTTなどが、それぞれ会社《かいしゃ》の名前《なまえ》を変《か》えられるようにします。",
      "hs": "NTTなどが、それぞれ商号（会社の名前）を変えられるようにします。",
      "std": "日本電信電話株式会社等が、それぞれ商号を変更できるようにする。",
      "univ": "日本電信電話株式会社等がそれぞれその商号の変更をできるようにする。"
    },
    {
      "es": "日本《にっぽん》の国籍《こくせき》がない人《ひと》が会社《かいしゃ》の役員《やくいん》になることのきまりを、ゆるくします。※正確《せいかく》には、代表取締役《だいひょうとりしまりやく》になることと、取締役《とりしまりやく》か監査役《かんさやく》の三分《さんぶん》の一《いち》以上《いじょう》をしめることだけを禁止《きんし》します。",
      "hs": "日本の国籍《こくせき》がない人について、NTTなどの代表取締役《とりしまりやく》になることと、取締役《とりしまりやく》か監査役《かんさやく》（会社の仕事をチェックする役員）の三分の一以上をしめることを禁止します。また、NTTの取締役《とりしまりやく》と監査役《かんさやく》を選んだりやめさせたりする決定に、総務大臣の認可《にんか》をいらなくします。",
      "std": "日本の国籍を有しない人が、日本電信電話株式会社等の代表取締役に就くことと、取締役または監査役の三分の一以上を占めることを禁止する。また、日本電信電話株式会社の取締役・監査役の選任・解任の決議について総務大臣の認可を不要とする。",
      "univ": "日本の国籍を有しない人が、日本電信電話株式会社等の代表取締役に就任すること及び取締役又は監査役の三分の一以上を占めることを禁止するとともに、日本電信電話株式会社の取締役及び監査役の選任及び解任の決議について総務大臣の認可を不要とする。"
    },
    {
      "es": "NTTが、もうけたお金《かね》（剰余金《じょうよきん》）の使《つか》い道《みち》を決《き》めるとき、国《くに》の大臣《だいじん》のゆるしをいらなくします。",
      "hs": "NTTの剰余金《じょうよきん》（会社に残った利益など）の処分《しょぶん》の決定に、総務大臣の認可《にんか》をいらなくします。",
      "std": "日本電信電話株式会社の剰余金の処分の決議について、総務大臣の認可を不要とする。",
      "univ": "日本電信電話株式会社の剰余金の処分の決議について、総務大臣の認可を不要とする。"
    },
    {
      "es": "政府《せいふ》は、NTTなどのしくみのあり方《かた》を考《かんが》え、令和《れいわ》7年《ねん》の国会《こっかい》（常会《じょうかい》）をめあてに、必要《ひつよう》な法律案《ほうりつあん》を出《だ》すこととします。",
      "hs": "政府は、NTTなどの制度のあり方を検討《けんとう》し、その結果をもとに、令和7年に開かれる国会の常会（毎年開かれる通常の国会）をめどに、必要な法律案を国会に出すこととします。",
      "std": "政府は、日本電信電話株式会社等に係る制度の在り方を検討し、その結果に基づき、令和7年に開会される国会の常会を目途として、必要な措置を講ずるための法律案を国会に提出する。",
      "univ": "政府は、日本電信電話株式会社等に係る制度の在り方について検討を加え、その結果に基づいて、令和7年に開会される国会の常会を目途として、必要な措置を講ずるための法律案を国会に提出するものとする。"
    },
    {
      "es": "この法律《ほうりつ》は、出《だ》された日《ひ》の次《つぎ》の日《ひ》から使《つか》われます。",
      "hs": "公布《こうふ》の日の翌日《よくじつ》から施行《しこう》します。",
      "std": "公布の日の翌日から施行する。",
      "univ": "この法律は、公布の日の翌日から施行する。"
    }
  ]
}
